<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>vBudget - Super Admin</title>
  <link rel="stylesheet" href="/style.css">
  <style>
    .sa-badge {
      display: inline-block;
      background: #e74c3c;
      color: #fff;
      font-size: 11px;
      font-weight: 600;
      padding: 2px 8px;
      border-radius: 10px;
      letter-spacing: 0.3px;
      vertical-align: middle;
    }
    .hint {
      font-size: 0.85em;
      color: #666;
      margin-top: 4px;
    }
    .cascade-warning {
      color: #e74c3c;
      font-weight: 600;
      font-size: 0.9em;
    }
    .two-panel {
      display: flex;
      flex-direction: column;
      gap: 20px;
    }
    .panel-selector {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 8px;
    }
    .panel-selector select {
      flex: 1;
      max-width: 400px;
    }
  </style>
</head>
<body>
  <h1>Super Admin</h1>

  <div class="tabs">
    <button class="tab active" data-tab="projects">Projects</button>
    <button class="tab" data-tab="users">Global Users</button>
    <button class="tab" data-tab="memberships">Memberships</button>
  </div>

  <!-- ==================== PROJECTS TAB ==================== -->
  <div id="tab-projects" class="tab-content active">
    <div class="card">
      <h2>All Projects</h2>
      <form id="projectForm" class="inline-form">
        <input type="text" name="name" placeholder="Project name" required>
        <input type="text" name="subtitle" placeholder="Subtitle \(optional\)">
        <button type="submit">Create Project</button>
      </form>
      <div id="projectResult"></div>
      <table class="data-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Subtitle</th>
            <th>Created</th>
            <th>Members</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody id="projectBody"></tbody>
      </table>
    </div>
  </div>

  <!-- ==================== GLOBAL USERS TAB ==================== -->
  <div id="tab-users" class="tab-content">
    <div class="card">
      <h2>Global Users</h2>
      <form id="userForm" class="inline-form" style="flex-wrap:wrap">
        <input type="email" name="email" placeholder="Email" required>
        <div class="password-wrapper">
          <input type="password" name="password" placeholder="Password" required>
          <button type="button" class="password-toggle" onclick="togglePw\(this\)">Show</button>
        </div>
        <label style="flex-direction:row;align-items:center;gap:6px;font-weight:400">
          <input type="checkbox" name="isSuperAdmin"> Super Admin
        </label>
        <button type="submit">Create User</button>
      </form>
      <p class="hint">Password must be at least 6 characters.</p>
      <div id="userResult"></div>
      <table class="data-table">
        <thead>
          <tr>
            <th>Email</th>
            <th>Super Admin</th>
            <th>Projects</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody id="userBody"></tbody>
      </table>
    </div>
  </div>

  <!-- ==================== MEMBERSHIPS TAB ==================== -->
  <div id="tab-memberships" class="tab-content">
    <div class="card">
      <h2>Project Memberships</h2>
      <div class="panel-selector">
        <label style="font-weight:600;margin:0">Project:</label>
        <select id="membershipProject" onchange="loadMemberships\(\)">
          <option value="">-- Select a project --</option>
        </select>
      </div>

      <div id="membershipPanel" style="display:none">
        <h3 style="margin-top:16px">Members</h3>
        <form id="memberForm" class="inline-form" style="flex-wrap:wrap">
          <input type="email" name="email" placeholder="User email" required list="userEmailList">
          <datalist id="userEmailList"></datalist>
          <select name="role">
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
          <select name="positionId">
            <option value="">-- No position --</option>
          </select>
          <button type="submit">Add Member</button>
        </form>
        <div id="memberResult"></div>
        <table class="data-table">
          <thead>
            <tr>
              <th>Email</th>
              <th>Role</th>
              <th>Position</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody id="memberBody"></tbody>
        </table>
      </div>
    </div>

    <div class="card" id="positionsCard" style="display:none">
      <h2>Positions</h2>
      <form id="positionForm" class="inline-form">
        <input type="text" name="name" placeholder="Position name" required>
        <button type="submit">Add Position</button>
      </form>
      <div id="positionResult"></div>
      <table class="data-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody id="positionBody"></tbody>
      </table>
    </div>
  </div>

  <p><a href="/">Back</a> | <a href="/admin">Admin Panel</a> | <a href="/logout">Logout</a> | <span id="saVersion" style="color:#999; font-size:0.85em"></span></p>

  <script>
    /* ===== Helpers ===== */
    function togglePw\(btn\) {
      const i = btn.previousElementSibling;
      const show = i.type === 'password';
      i.type = show ? 'text' : 'password';
      btn.textContent = show ? 'Hide' : 'Show';
    }
    const esc = t => { const d = document.createElement\('div'\); d.textContent = t || ''; return d.innerHTML; };
    const msg = \(id, t, err\) => { const e = document.getElementById\(id\); e.textContent = t; e.className = 'message ' + \(err ? 'error' : 'success'\); setTimeout\(\(\) => e.textContent = '', 3000\); };
    const fmtDate = d => d ? new Date\(d\).toLocaleDateString\('de-DE'\) : '';
    const api = async \(url, opts\) => {
      const res = await fetch\(url, opts\);
      return res.json\(\);
    };
    const jsonOpts = \(method, body\) => \({
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify\(body\)
    }\);

    /* ===== Tab switching ===== */
    document.querySelectorAll\('.tab'\).forEach\(tab => {
      tab.addEventListener\('click', \(\) => {
        document.querySelectorAll\('.tab'\).forEach\(t => t.classList.remove\('active'\)\);
        document.querySelectorAll\('.tab-content'\).forEach\(c => c.classList.remove\('active'\)\);
        tab.classList.add\('active'\);
        document.getElementById\('tab-' + tab.dataset.tab\).classList.add\('active'\);
      }\);
    }\);

    /* ========================================================
       PROJECTS TAB
       ======================================================== */
    let projectsCache = [];

    async function loadProjects\(\) {
      try {
        projectsCache = await api\('/api/superadmin/projects'\);
        const tbody = document.getElementById\('projectBody'\);
        tbody.innerHTML = projectsCache.map\(p => {
          const safeName = esc\(p.name\).replace\(/'/g, '&#39;'\);
          const safeSub = esc\(p.subtitle || ''\).replace\(/'/g, '&#39;'\);
          return `<tr data-id="${p.id}">
            <td>${p.id}</td>
            <td>${esc\(p.name\)}</td>
            <td>${esc\(p.subtitle || ''\)}</td>
            <td>${fmtDate\(p.created_at\)}</td>
            <td>${p.member_count != null ? p.member_count : '—'}</td>
            <td>
              <button class="small secondary" onclick="editProject\(${p.id}, '${safeName}', '${safeSub}'\)">Edit</button>
              <button class="small danger" onclick="deleteProject\(${p.id}, '${safeName}'\)">Delete</button>
            </td>
          </tr>`;
        }\).join\(''\);
        // Also update membership project dropdown
        populateProjectDropdown\(\);
      } catch \(e\) { console.error\('Error loading projects', e\); }
    }

    document.getElementById\('projectForm'\).onsubmit = async e => {
      e.preventDefault\(\);
      const f = e.target;
      const j = await api\('/api/superadmin/projects', jsonOpts\('POST', {
        name: f.name.value,
        subtitle: f.subtitle.value
      }\)\);
      if \(j.ok || j.id\) { msg\('projectResult', 'Project created', false\); f.reset\(\); loadProjects\(\); }
      else msg\('projectResult', j.error || 'Error', true\);
    };

    async function editProject\(id, oldName, oldSubtitle\) {
      const newName = prompt\('Project name:', oldName\);
      if \(newName === null\) return;
      const newSubtitle = prompt\('Subtitle:', oldSubtitle\);
      if \(newSubtitle === null\) return;
      const j = await api\('/api/superadmin/projects/' + id, jsonOpts\('PUT', {
        name: newName,
        subtitle: newSubtitle
      }\)\);
      if \(j.ok\) { msg\('projectResult', 'Project updated', false\); loadProjects\(\); }
      else msg\('projectResult', j.error || 'Error', true\);
    }

    async function deleteProject\(id, name\) {
      if \(!confirm\('DELETE project "' + name + '"?\\n\\nWARNING: This will CASCADE-delete all bills, budgets, members, and data associated with this project. This cannot be undone!'\)\) return;
      if \(!confirm\('Are you absolutely sure? Type OK to confirm deletion of "' + name + '".'\)\) return;
      const j = await api\('/api/superadmin/projects/' + id, { method: 'DELETE' }\);
      if \(j.ok\) { msg\('projectResult', 'Project deleted', false\); loadProjects\(\); }
      else msg\('projectResult', j.error || 'Error', true\);
    }

    /* ========================================================
       GLOBAL USERS TAB
       ======================================================== */
    let usersCache = [];

    async function loadUsers\(\) {
      try {
        usersCache = await api\('/api/superadmin/users'\);
        const tbody = document.getElementById\('userBody'\);
        tbody.innerHTML = usersCache.map\(u => {
          const safeEmail = esc\(u.email\).replace\(/'/g, '&#39;'\);
          const badge = u.is_super_admin ? '<span class="sa-badge">Super Admin</span>' : '';
          return `<tr>
            <td>${esc\(u.email\)}</td>
            <td>${badge}</td>
            <td>${u.project_count != null ? u.project_count : '—'}</td>
            <td>
              <button class="small secondary" onclick="resetPassword\('${safeEmail}'\)">Reset PW</button>
              <button class="small secondary" onclick="toggleSuperAdmin\('${safeEmail}', ${u.is_super_admin ? 1 : 0}\)">${u.is_super_admin ? 'Revoke SA' : 'Grant SA'}</button>
              <button class="small danger" onclick="deleteUser\('${safeEmail}'\)">Delete</button>
            </td>
          </tr>`;
        }\).join\(''\);
        // Also update email datalist for membership tab
        populateEmailDatalist\(\);
      } catch \(e\) { console.error\('Error loading users', e\); }
    }

    document.getElementById\('userForm'\).onsubmit = async e => {
      e.preventDefault\(\);
      const f = e.target;
      const pw = f.password.value;
      if \(pw.length < 6\) { msg\('userResult', 'Password must be at least 6 characters', true\); return; }
      const j = await api\('/api/superadmin/users', jsonOpts\('POST', {
        email: f.email.value,
        password: pw,
        isSuperAdmin: f.isSuperAdmin.checked
      }\)\);
      if \(j.ok || j.id\) { msg\('userResult', 'User created', false\); f.reset\(\); loadUsers\(\); }
      else msg\('userResult', j.error || 'Error', true\);
    };

    async function resetPassword\(email\) {
      const newPw = prompt\('New password for ' + email + ':'\);
      if \(!newPw\) return;
      if \(newPw.length < 6\) { msg\('userResult', 'Password must be at least 6 characters', true\); return; }
      const j = await api\('/api/superadmin/users/' + encodeURIComponent\(email\), jsonOpts\('PUT', {
        password: newPw
      }\)\);
      if \(j.ok\) msg\('userResult', 'Password reset for ' + email, false\);
      else msg\('userResult', j.error || 'Error', true\);
    }

    async function toggleSuperAdmin\(email, currentVal\) {
      const newVal = !currentVal;
      const action = newVal ? 'Grant' : 'Revoke';
      if \(!confirm\(action + ' Super Admin for ' + email + '?'\)\) return;
      const j = await api\('/api/superadmin/users/' + encodeURIComponent\(email\), jsonOpts\('PUT', {
        isSuperAdmin: newVal
      }\)\);
      if \(j.ok\) { msg\('userResult', action + 'd Super Admin for ' + email, false\); loadUsers\(\); }
      else msg\('userResult', j.error || 'Error', true\);
    }

    async function deleteUser\(email\) {
      if \(!confirm\('Delete user "' + email + '"? This will remove them from all projects.'\)\) return;
      const j = await api\('/api/superadmin/users/' + encodeURIComponent\(email\), { method: 'DELETE' }\);
      if \(j.ok\) { msg\('userResult', 'User deleted', false\); loadUsers\(\); }
      else msg\('userResult', j.error || 'Error', true\);
    }

    /* ========================================================
       MEMBERSHIPS TAB
       ======================================================== */
    let positionsCache = [];

    function populateProjectDropdown\(\) {
      const sel = document.getElementById\('membershipProject'\);
      const curVal = sel.value;
      sel.innerHTML = '<option value="">-- Select a project --</option>' +
        projectsCache.map\(p => `<option value="${p.id}">${esc\(p.name\)}</option>`\).join\(''\);
      if \(curVal\) sel.value = curVal;
    }

    function populateEmailDatalist\(\) {
      const dl = document.getElementById\('userEmailList'\);
      dl.innerHTML = usersCache.map\(u => `<option value="${esc\(u.email\)}">`\).join\(''\);
    }

    function populatePositionSelect\(\) {
      const sel = document.querySelector\('#memberForm select[name="positionId"]'\);
      sel.innerHTML = '<option value="">-- No position --</option>' +
        positionsCache.map\(p => `<option value="${p.id}">${esc\(p.name\)}</option>`\).join\(''\);
    }

    function getSelectedProjectId\(\) {
      return document.getElementById\('membershipProject'\).value;
    }

    async function loadMemberships\(\) {
      const pid = getSelectedProjectId\(\);
      const panel = document.getElementById\('membershipPanel'\);
      const posCard = document.getElementById\('positionsCard'\);

      if \(!pid\) {
        panel.style.display = 'none';
        posCard.style.display = 'none';
        return;
      }
      panel.style.display = 'block';
      posCard.style.display = 'block';

      await loadPositionsForProject\(pid\);
      populatePositionSelect\(\);
      await loadMembersForProject\(pid\);
    }

    async function loadMembersForProject\(pid\) {
      const tbody = document.getElementById\('memberBody'\);
      try {
        const members = await api\('/api/superadmin/projects/' + pid + '/members'\);
        tbody.innerHTML = members.map\(m => {
          const posOptions = '<option value="">-- None --</option>' + positionsCache.map\(p =>
            `<option value="${p.id}" ${p.id === m.positionId ? 'selected' : ''}>${esc\(p.name\)}</option>`
          \).join\(''\);
          const roleSelect = `<select onchange="updateMember\(${m.id}, {role: this.value}\)">
            <option value="user" ${m.role === 'user' ? 'selected' : ''}>User</option>
            <option value="admin" ${m.role === 'admin' ? 'selected' : ''}>Admin</option>
          </select>`;
          const posSelect = `<select onchange="updateMember\(${m.id}, {positionId: this.value ? parseInt\(this.value\) : null}\)">${posOptions}</select>`;
          const safeEmail = esc\(m.email\).replace\(/'/g, '&#39;'\);
          return `<tr>
            <td>${esc\(m.email\)}</td>
            <td>${roleSelect}</td>
            <td>${posSelect}</td>
            <td>
              <button class="small danger" onclick="removeMember\(${m.id}, '${safeEmail}'\)">Remove</button>
            </td>
          </tr>`;
        }\).join\(''\);
      } catch \(e\) {
        tbody.innerHTML = '<tr><td colspan="4">Error loading members</td></tr>';
      }
    }

    async function loadPositionsForProject\(pid\) {
      try {
        positionsCache = await api\('/api/superadmin/projects/' + pid + '/positions'\);
        const tbody = document.getElementById\('positionBody'\);
        tbody.innerHTML = positionsCache.map\(p => {
          const safeName = esc\(p.name\).replace\(/'/g, '&#39;'\);
          const isMisc = p.name === 'Misc';
          return `<tr data-id="${p.id}">
            <td>${p.id}</td>
            <td>${esc\(p.name\)}</td>
            <td>${isMisc ? '' : `<button class="small secondary" onclick="renamePosition\(${p.id}, '${safeName}'\)">Rename</button>
              <button class="small danger" onclick="deletePosition\(${p.id}\)">Delete</button>`}</td>
          </tr>`;
        }\).join\(''\);
      } catch \(e\) { console.error\('Error loading positions', e\); }
    }

    document.getElementById\('memberForm'\).onsubmit = async e => {
      e.preventDefault\(\);
      const f = e.target;
      const pid = getSelectedProjectId\(\);
      if \(!pid\) { msg\('memberResult', 'Select a project first', true\); return; }
      const body = {
        email: f.email.value,
        role: f.role.value
      };
      if \(f.positionId.value\) body.positionId = parseInt\(f.positionId.value\);
      const j = await api\('/api/superadmin/projects/' + pid + '/members', jsonOpts\('POST', body\)\);
      if \(j.ok || j.id\) { msg\('memberResult', 'Member added', false\); f.reset\(\); loadMemberships\(\); }
      else msg\('memberResult', j.error || 'Error', true\);
    };

    async function updateMember\(memberId, data\) {
      const pid = getSelectedProjectId\(\);
      if \(!pid\) return;
      const j = await api\('/api/superadmin/projects/' + pid + '/members/' + memberId, jsonOpts\('PUT', data\)\);
      if \(j.ok\) loadMembersForProject\(pid\);
      else msg\('memberResult', j.error || 'Error', true\);
    }

    async function removeMember\(memberId, email\) {
      const pid = getSelectedProjectId\(\);
      if \(!pid\) return;
      if \(!confirm\('Remove ' + email + ' from this project?'\)\) return;
      const j = await api\('/api/superadmin/projects/' + pid + '/members/' + memberId, { method: 'DELETE' }\);
      if \(j.ok\) { msg\('memberResult', 'Member removed', false\); loadMemberships\(\); }
      else msg\('memberResult', j.error || 'Error', true\);
    }

    document.getElementById\('positionForm'\).onsubmit = async e => {
      e.preventDefault\(\);
      const f = e.target;
      const pid = getSelectedProjectId\(\);
      if \(!pid\) { msg\('positionResult', 'Select a project first', true\); return; }
      const j = await api\('/api/superadmin/projects/' + pid + '/positions', jsonOpts\('POST', {
        name: f.name.value
      }\)\);
      if \(j.ok || j.id\) { msg\('positionResult', 'Position added', false\); f.reset\(\); loadMemberships\(\); }
      else msg\('positionResult', j.error || 'Error', true\);
    };

    async function renamePosition\(posId, oldName\) {
      const pid = getSelectedProjectId\(\);
      if \(!pid\) return;
      const newName = prompt\('Rename position "' + oldName + '" to:', oldName\);
      if \(!newName || newName === oldName\) return;
      const j = await api\('/api/superadmin/projects/' + pid + '/positions/' + posId, jsonOpts\('PUT', {
        name: newName
      }\)\);
      if \(j.ok\) { msg\('positionResult', 'Position renamed', false\); loadMemberships\(\); }
      else msg\('positionResult', j.error || 'Error', true\);
    }

    async function deletePosition\(posId\) {
      const pid = getSelectedProjectId\(\);
      if \(!pid\) return;
      if \(!confirm\('Delete this position? Members with this position will revert to unset.'\)\) return;
      const j = await api\('/api/superadmin/projects/' + pid + '/positions/' + posId, { method: 'DELETE' }\);
      if \(j.ok\) { msg\('positionResult', 'Deleted', false\); loadMemberships\(\); }
      else msg\('positionResult', j.error || 'Error', true\);
    }

    /* ===== Init ===== */
    loadProjects\(\);
    loadUsers\(\);
    fetch\('/api/project-info'\).then\(r => r.json\(\)\).then\(d => {
      if \(d.version\) document.getElementById\('saVersion'\).textContent = 'v' + d.version;
    }\);
  </script>
</body>
</html>
ENDOFFILE)
